import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Link, useParams } from 'react-router-dom';

import { Alert, Button, Card, Flex, Typography } from 'antd';

import DeleteIcon from 'assets/images/icons/delete.svg?react';
import EditIcon from 'assets/images/icons/edit.svg?react';
import WarningIcon from 'assets/images/icons/warning.svg?react';
import StatsIcon from 'assets/images/menu/stats.svg?react';
import WalletIcon from 'assets/images/menu/wallet.svg?react';
import {
	ChannelAvatar,
	ChannelStatusAlert,
	ChannelSubscribers,
	DeleteChannelModal,
	useSourcesRetrieveQuery,
} from 'entities/Channel';
import { EFilters } from 'features/Filters';
import { Planner } from 'features/Planner';
import { CATEGORIES, COUNTRIES, SOURCE_LANGUAGES } from 'shared/consts';
import { useBackButton, useNotFoundError } from 'shared/hooks';
import { EMainRoutes, EYmPageScreen } from 'shared/typings';
import { ButtonStyleLink, Content, DashboardLink, LastProfit, OverlayLoader, Page } from 'shared/ui';
import { sendYmEvent } from 'shared/utils';

import styles from './Channel.module.scss';

interface IChannelProps extends HTMLAttributes<HTMLDivElement> {}

export const Channel: FC<IChannelProps> = () => {
	const { t } = useTranslation();
	const params = useParams<{ id: string }>();
	const { data: channel, isFetching, error } = useSourcesRetrieveQuery(params?.id || '');

	useNotFoundError(error);
	useBackButton(`/${EMainRoutes.CHANNELS}`);

	const [isDeleting, setIsDeleting] = useState(false);

	if (!channel) return null;

	return (
		<Page className={styles.page}>
			<Content className={styles.content} bordered={false}>
				{isFetching && <OverlayLoader />}
				<Flex vertical gap={8}>
					<Flex vertical gap={12}>
						<Flex justify="space-between" gap={12}>
							<Flex gap={8}>
								<ChannelAvatar name={channel?.name} logo={channel?.logo_url} status={channel?.status} size={80} />
								<Flex vertical gap={4}>
									<Typography.Title level={4} style={{ margin: 0 }}>
										{channel?.name}
									</Typography.Title>
									<ChannelSubscribers count={channel?.subscribers_count} />
								</Flex>
							</Flex>
							<Button
								className={styles.delete}
								icon={<DeleteIcon />}
								variant="text"
								color="danger"
								onClick={() => setIsDeleting(true)}
							/>
						</Flex>

						<Typography.Text type="secondary">{channel?.description}</Typography.Text>
					</Flex>

					<Flex gap={8}>
						<DashboardLink
							to={`/${EMainRoutes.REPORTS}?${EFilters.SOURCE}=${channel?.uuid}`}
							onClick={() => sendYmEvent('click_statistics', { page_screen: EYmPageScreen.CHANNEL_DETAIL_SCREEN })}
							title={t('Статистика')}
							icon={<StatsIcon />}
							type="vertical"
						/>
						<DashboardLink
							to={`/${EMainRoutes.FINANCES}?${EFilters.SOURCE}=${channel?.uuid}`}
							onClick={() => sendYmEvent('click_finance', { page_screen: EYmPageScreen.CHANNEL_DETAIL_SCREEN })}
							title={t('Финансы')}
							icon={<WalletIcon />}
							type="vertical"
						/>
					</Flex>

					<ChannelStatusAlert status={channel?.status} />

					<LastProfit channelId={channel?.uuid} />

					<Card variant="borderless" styles={{ body: { padding: '12px' } }}>
						<Flex justify="space-between" gap={2}>
							<Flex vertical gap={8}>
								<Typography.Text type="secondary" style={{ fontSize: 12 }}>
									{t('Категории канала')}
								</Typography.Text>

								<Flex wrap className={styles.categories}>
									{channel?.categories?.map((category) => (
										<Typography.Text key={category}>{CATEGORIES[category] || category}</Typography.Text>
									))}
								</Flex>
							</Flex>

							<ButtonStyleLink
								to={`/${EMainRoutes.CHANNELS}/${EMainRoutes.EDIT}/${channel?.uuid}`}
								size="small"
								type="link"
								style={{ width: 18, height: 18 }}
								icon={<EditIcon />}
							/>
						</Flex>
					</Card>

					<Card variant="borderless" styles={{ body: { padding: '12px' } }}>
						<Flex justify="space-between" gap={2}>
							<Flex vertical gap={8}>
								<Typography.Text type="secondary" style={{ fontSize: 12 }}>
									{t('Язык')}
								</Typography.Text>

								<Flex wrap className={styles.categories}>
									{channel?.languages?.map((language) => (
										<Typography.Text key={language}>{SOURCE_LANGUAGES[language] || language}</Typography.Text>
									))}
								</Flex>
							</Flex>

							<ButtonStyleLink
								to={`/${EMainRoutes.CHANNELS}/${EMainRoutes.EDIT}/${channel?.uuid}`}
								size="small"
								type="link"
								style={{ width: 18, height: 18 }}
								icon={<EditIcon />}
							/>
						</Flex>
					</Card>

					<Card variant="borderless" styles={{ body: { padding: '12px' } }}>
						<Flex justify="space-between" gap={2}>
							<Flex vertical gap={8}>
								<Typography.Text type="secondary" style={{ fontSize: 12 }}>
									{t('ГЕО канала')}
								</Typography.Text>

								<Flex wrap className={styles.categories}>
									{channel?.countries?.map((country) => (
										<Typography.Text key={country}>{COUNTRIES[country] || country}</Typography.Text>
									))}
								</Flex>

								{channel?.countries?.includes('RU') && (
									<Alert
										message={
											<>
												<Typography.Text>{t('Применяется ERID.')}</Typography.Text> <Link to="/">{t('Подробнее')}</Link>
											</>
										}
										type="info"
										banner
										showIcon
										icon={<WarningIcon />}
									/>
								)}
							</Flex>

							<ButtonStyleLink
								to={`/${EMainRoutes.CHANNELS}/${EMainRoutes.EDIT}/${channel?.uuid}`}
								size="small"
								type="link"
								style={{ width: 18, height: 18 }}
								icon={<EditIcon />}
							/>
						</Flex>
					</Card>
				</Flex>
			</Content>

			<Content filled className={styles.planner}>
				<Flex vertical gap={12}>
					<Typography.Title level={4} style={{ margin: 0 }}>
						{t('Запланированные посты')}
					</Typography.Title>
					<Planner isInner channelIds={[channel?.uuid || '']} />
				</Flex>
			</Content>

			<DeleteChannelModal channel={channel} open={isDeleting} onCancel={() => setIsDeleting(false)} />
		</Page>
	);
};

export default Channel;
