import { FC, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';

import { Modal, ModalProps, notification } from 'antd';

import { SourceRead, useSourcesDestroyMutation } from 'entities/Channel';
import { EMainRoutes } from 'shared/typings';

interface IDeleteChannelModalProps extends ModalProps {
	channel: SourceRead;
}

export const DeleteChannelModal: FC<IDeleteChannelModalProps> = ({ channel, onCancel, ...props }) => {
	const { t } = useTranslation();
	const navigate = useNavigate();
	const [deleteChannel, { isLoading, isSuccess }] = useSourcesDestroyMutation();

	useEffect(() => {
		if (isSuccess) {
			navigate(`/${EMainRoutes.CHANNELS}`);
			onCancel?.({} as React.MouseEvent<HTMLButtonElement>);
			notification.success({
				message: t('Канал успешно удален'),
				placement: 'bottom',
				showProgress: true,
				pauseOnHover: true,
			});
		}
	}, [isSuccess, onCancel, navigate, t]);

	return (
		<Modal
			{...props}
			okType="danger"
			okText={t('Удалить')}
			cancelText={t('Отмена')}
			onOk={() => {
				deleteChannel(channel.uuid);
			}}
			onCancel={onCancel}
			title={t('Вы уверены, что хотите удалить канал "{{channel}}"?', {
				channel: channel.name,
			})}
			styles={{
				header: {
					padding: '24px 0 12px',
				},
			}}
			okButtonProps={{
				loading: isLoading,
				disabled: isLoading,
			}}
		/>
	);
};
